"use client"

/**
 * Interactive job feed built ONLY from fields you already have:
 * id, title, company, locationLabel, skills, fieldLabel, postedAt, closingDate
 *
 * Added interactions:
 *  1. Colored initials avatar (no images needed)
 *  2. "New" and "Closing soon" badges + relative time ("3h ago")
 *  3. Skill chips (tap a skill to search it)
 *  4. Tap location / sector on a card to filter by it
 *  5. Filter chip row (sector + city) built automatically from your data
 *  6. Sort toggle: Newest / Closing soon
 *  7. "Saved only" toggle with live count
 *  8. Animated bookmark button + toast feedback
 *  9. Share button (Web Share API, falls back to copy)
 * 10. Search match highlighting
 * 11. Back-to-top floating button
 * 12. "New jobs since your last visit" banner
 *
 * Replace your current home-screen file with this. It defines its own card,
 * so FeedCard is no longer imported (keep your old one for the detail view).
 */

import { useMemo, useEffect, useRef, useState, useCallback } from "react"
import {
  AlertCircle, Search, X, Bookmark, Share2, MapPin, Clock,
  ArrowUp, Briefcase, Check,
} from "lucide-react"
import { useApp } from "@/components/app-provider"
import { Button } from "@/components/ui/button"

const PAGE_SIZE = 10
const HOUR = 3_600_000
const DAY = 24 * HOUR

// ─── Helpers ──────────────────────────────────────────────────────────────────

function parseDate(iso?: string): number {
  if (!iso) return 0
  const ms = new Date(iso).getTime()
  return isNaN(ms) ? 0 : ms
}

function isPastClosingDate(closingDate?: string): boolean {
  const t = parseDate(closingDate)
  return t > 0 && t < Date.now()
}

function timeAgo(iso?: string): string {
  const t = parseDate(iso)
  if (!t) return ""
  const diff = Date.now() - t
  const m = Math.floor(diff / 60_000)
  if (m < 1) return "Just now"
  if (m < 60) return `${m}m ago`
  const h = Math.floor(m / 60)
  if (h < 24) return `${h}h ago`
  const d = Math.floor(h / 24)
  if (d < 7) return `${d}d ago`
  if (d < 30) return `${Math.floor(d / 7)}w ago`
  return new Date(t).toLocaleDateString(undefined, { month: "short", day: "numeric" })
}

function daysLeft(closingDate?: string): number | null {
  const t = parseDate(closingDate)
  if (!t) return null
  return Math.ceil((t - Date.now()) / DAY)
}

function splitSkills(skills?: string): string[] {
  if (!skills) return []
  return skills.split(/[,;|\n]/).map((s) => s.trim()).filter(Boolean)
}

// Wrap matching text in <mark> so users see why a job matched.
function Highlight({ text, query }: { text?: string; query: string }) {
  if (!text) return null
  const q = query.trim()
  if (!q) return <>{text}</>
  const i = text.toLowerCase().indexOf(q.toLowerCase())
  if (i === -1) return <>{text}</>
  return (
    <>
      {text.slice(0, i)}
      <mark className="rounded bg-primary/20 px-0.5 text-foreground">{text.slice(i, i + q.length)}</mark>
      {text.slice(i + q.length)}
    </>
  )
}

// ─── Avatar (no image needed) ─────────────────────────────────────────────────

function CompanyAvatar({ name = "?" }: { name?: string }) {
  const initials = name.split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase() || "?"
  const hue = [...name].reduce((h, c) => h + c.charCodeAt(0), 0) % 360
  return (
    <div
      className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-sm font-bold text-white"
      style={{ backgroundColor: `hsl(${hue} 50% 42%)` }}
      aria-hidden
    >
      {initials}
    </div>
  )
}

// ─── Card ─────────────────────────────────────────────────────────────────────

type Job = any // swap for your real Job type

function JobCard({
  job, saved, query, onOpen, onToggleSave, onSkill, onSector, onCity, onToast,
}: {
  job: Job
  saved: boolean
  query: string
  onOpen: () => void
  onToggleSave: () => void
  onSkill: (s: string) => void
  onSector: (s: string) => void
  onCity: (s: string) => void
  onToast: (msg: string) => void
}) {
  const [pop, setPop] = useState(false)
  const isNew = Date.now() - parseDate(job.postedAt) < 2 * DAY
  const left = daysLeft(job.closingDate)
  const closingSoon = left !== null && left >= 0 && left <= 3
  const skills = splitSkills(job.skills)

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation()
    setPop(true)
    setTimeout(() => setPop(false), 300)
    onToggleSave()
    onToast(saved ? "Removed from saved" : "Job saved")
  }

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation()
    const text = `${job.title} at ${job.company}`
    try {
      if (navigator.share) {
        await navigator.share({ title: job.title, text, url: window.location.href })
      } else {
        await navigator.clipboard.writeText(`${text} - ${window.location.href}`)
        onToast("Link copied")
      }
    } catch {
      /* user cancelled share */
    }
  }

  const stop = (fn: () => void) => (e: React.MouseEvent) => {
    e.stopPropagation()
    fn()
  }

  return (
    <article
      onClick={onOpen}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => e.key === "Enter" && onOpen()}
      className="cursor-pointer rounded-2xl border border-border bg-card p-4 shadow-sm transition active:scale-[0.99] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30"
    >
      {/* Top row: avatar, title, bookmark */}
      <div className="flex items-start gap-3">
        <CompanyAvatar name={job.company} />
        <div className="min-w-0 flex-1">
          <h3 className="text-[15px] font-semibold leading-snug text-foreground">
            <Highlight text={job.title} query={query} />
          </h3>
          <p className="truncate text-sm text-muted-foreground">
            <Highlight text={job.company} query={query} />
          </p>
        </div>
        <button
          type="button"
          onClick={handleSave}
          aria-label={saved ? "Remove from saved" : "Save job"}
          aria-pressed={saved}
          className={`-mr-1 -mt-1 flex h-9 w-9 items-center justify-center rounded-full transition hover:bg-secondary ${
            pop ? "scale-125" : "scale-100"
          }`}
        >
          <Bookmark className={`h-5 w-5 ${saved ? "fill-primary text-primary" : "text-muted-foreground"}`} />
        </button>
      </div>

      {/* Meta row: time, badges */}
      <div className="mt-2.5 flex flex-wrap items-center gap-x-3 gap-y-1.5 text-xs text-muted-foreground">
        <span className="inline-flex items-center gap-1">
          <Clock className="h-3.5 w-3.5" />
          {timeAgo(job.postedAt)}
        </span>
        {isNew && (
          <span className="rounded-full bg-primary/10 px-2 py-0.5 font-medium text-primary">New</span>
        )}
        {closingSoon && (
          <span className="rounded-full bg-destructive/10 px-2 py-0.5 font-medium text-destructive">
            {left === 0 ? "Closes today" : `Closes in ${left}d`}
          </span>
        )}
      </div>

      {/* Tappable location + sector */}
      <div className="mt-2.5 flex flex-wrap gap-2">
        {job.locationLabel && (
          <button
            type="button"
            onClick={stop(() => onCity(job.locationLabel))}
            className="inline-flex items-center gap-1 rounded-full border border-border px-2.5 py-1 text-xs text-foreground hover:bg-secondary"
          >
            <MapPin className="h-3 w-3" />
            <Highlight text={job.locationLabel} query={query} />
          </button>
        )}
        {job.fieldLabel && (
          <button
            type="button"
            onClick={stop(() => onSector(job.fieldLabel))}
            className="inline-flex items-center gap-1 rounded-full border border-border px-2.5 py-1 text-xs text-foreground hover:bg-secondary"
          >
            <Briefcase className="h-3 w-3" />
            <Highlight text={job.fieldLabel} query={query} />
          </button>
        )}
      </div>

      {/* Skill chips (tap = search that skill) */}
      {skills.length > 0 && (
        <div className="mt-2.5 flex flex-wrap gap-1.5">
          {skills.slice(0, 4).map((s) => (
            <button
              key={s}
              type="button"
              onClick={stop(() => onSkill(s))}
              className="rounded-md bg-secondary px-2 py-0.5 text-xs text-muted-foreground hover:text-foreground"
            >
              <Highlight text={s} query={query} />
            </button>
          ))}
          {skills.length > 4 && (
            <span className="px-1 py-0.5 text-xs text-muted-foreground">+{skills.length - 4}</span>
          )}
        </div>
      )}

      {/* Action bar */}
      <div className="mt-3 flex items-center justify-between border-t border-border pt-2.5">
        <button
          type="button"
          onClick={handleShare}
          className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-xs text-muted-foreground hover:bg-secondary hover:text-foreground"
        >
          <Share2 className="h-4 w-4" /> Share
        </button>
        <span className="text-xs font-medium text-primary">View details</span>
      </div>
    </article>
  )
}

// ─── Screen ───────────────────────────────────────────────────────────────────

type SortMode = "newest" | "closing"

export function HomeScreen() {
  const { allJobs, jobsError, retryLoadJobs, openJob, toggleSaved, isSaved } = useApp()
  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE)
  const [searchQuery, setSearchQuery] = useState("")
  const [sector, setSector] = useState<string | null>(null)
  const [city, setCity] = useState<string | null>(null)
  const [sort, setSort] = useState<SortMode>("newest")
  const [savedOnly, setSavedOnly] = useState(false)
  const [toast, setToast] = useState<string | null>(null)
  const [showTop, setShowTop] = useState(false)
  const [newSince, setNewSince] = useState(0)
  const sentinelRef = useRef<HTMLDivElement | null>(null)
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

  const showToast = useCallback((msg: string) => {
    setToast(msg)
    if (toastTimer.current) clearTimeout(toastTimer.current)
    toastTimer.current = setTimeout(() => setToast(null), 1800)
  }, [])

  // Reset pagination whenever any filter changes
  useEffect(() => {
    setVisibleCount(PAGE_SIZE)
  }, [searchQuery, sector, city, sort, savedOnly])

  // Back-to-top button visibility
  useEffect(() => {
    const onScroll = () => setShowTop(window.scrollY > 600)
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [])

  // "New since your last visit" banner (stored in localStorage)
  useEffect(() => {
    if (allJobs.length === 0) return
    try {
      const last = Number(localStorage.getItem("lastVisit") || 0)
      if (last) {
        setNewSince(allJobs.filter((j: Job) => parseDate(j.postedAt) > last).length)
      }
      localStorage.setItem("lastVisit", String(Date.now()))
    } catch {
      /* storage unavailable */
    }
  }, [allJobs.length]) // eslint-disable-line react-hooks/exhaustive-deps

  // Base list: open jobs only, de-duplicated
  const openJobs = useMemo(() => {
    const seen = new Set<string>()
    return allJobs.filter((job: Job) => {
      if (seen.has(job.id)) return false
      seen.add(job.id)
      return !isPastClosingDate(job.closingDate)
    })
  }, [allJobs])

  // Filter chips with counts, built from your data
  const sectorOptions = useMemo(() => countBy(openJobs, "fieldLabel"), [openJobs])
  const cityOptions = useMemo(() => countBy(openJobs, "locationLabel"), [openJobs])

  const feedJobs = useMemo(() => {
    const q = searchQuery.trim().toLowerCase()
    const list = openJobs.filter((job: Job) => {
      if (sector && job.fieldLabel !== sector) return false
      if (city && job.locationLabel !== city) return false
      if (savedOnly && !isSaved(job.id)) return false
      if (!q) return true
      return [job.title, job.company, job.locationLabel, job.skills, job.fieldLabel].some((v) =>
        v?.toLowerCase().includes(q),
      )
    })
    return list.sort((a: Job, b: Job) => {
      if (sort === "closing") {
        const ca = parseDate(a.closingDate) || Infinity
        const cb = parseDate(b.closingDate) || Infinity
        return ca - cb
      }
      return parseDate(b.postedAt) - parseDate(a.postedAt)
    })
    // isSaved changes identity with saved state in most providers; include it
  }, [openJobs, searchQuery, sector, city, savedOnly, sort, isSaved])

  const savedCount = useMemo(() => openJobs.filter((j: Job) => isSaved(j.id)).length, [openJobs, isSaved])
  const isLoading = allJobs.length === 0 && !jobsError
  const visibleJobs = feedJobs.slice(0, visibleCount)
  const hasMore = visibleCount < feedJobs.length
  const hasFilters = Boolean(searchQuery.trim() || sector || city || savedOnly)

  const clearAll = () => {
    setSearchQuery("")
    setSector(null)
    setCity(null)
    setSavedOnly(false)
  }

  // Infinite scroll
  useEffect(() => {
    const el = sentinelRef.current
    if (!el || !hasMore) return
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          setVisibleCount((c) => Math.min(c + PAGE_SIZE, feedJobs.length))
        }
      },
      { rootMargin: "200px" },
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [hasMore, feedJobs.length])

  return (
    <div className="flex flex-1 flex-col">
      <header className="sticky top-0 z-10 border-b border-border bg-background/95 pb-2.5 backdrop-blur [padding-top:calc(1.25rem+env(safe-area-inset-top))]">
        <div className="px-5">
          <h1 className="text-2xl font-bold text-foreground">Latest Jobs</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">
            {isLoading
              ? "Loading jobs…"
              : jobsError
                ? "Could not load jobs"
                : hasFilters
                  ? `${feedJobs.length} match${feedJobs.length === 1 ? "" : "es"} found`
                  : `${feedJobs.length} open role${feedJobs.length !== 1 ? "s" : ""}`}
          </p>

          {/* Search */}
          <div className="relative mt-3 flex items-center">
            <Search className="pointer-events-none absolute left-3.5 h-4 w-4 text-muted-foreground" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by title, company, skills, or city..."
              className="h-10 w-full rounded-xl border border-border bg-card pl-9 pr-9 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/25"
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery("")}
                aria-label="Clear search"
                className="absolute right-3 flex h-5 w-5 items-center justify-center rounded-full bg-secondary text-muted-foreground hover:text-foreground"
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
        </div>

        {/* Quick toggles: Saved + sort */}
        <div className="mt-2.5 flex items-center gap-2 overflow-x-auto px-5 pb-0.5 [scrollbar-width:none]">
          <Chip active={savedOnly} onClick={() => setSavedOnly((v) => !v)}>
            <Bookmark className="h-3.5 w-3.5" /> Saved {savedCount > 0 && `(${savedCount})`}
          </Chip>
          <Chip active={sort === "newest"} onClick={() => setSort("newest")}>Newest</Chip>
          <Chip active={sort === "closing"} onClick={() => setSort("closing")}>Closing soon</Chip>
          {hasFilters && (
            <button
              type="button"
              onClick={clearAll}
              className="shrink-0 px-2 text-xs font-medium text-primary"
            >
              Clear all
            </button>
          )}
        </div>

        {/* Sector chips */}
        {sectorOptions.length > 1 && (
          <div className="mt-2 flex items-center gap-2 overflow-x-auto px-5 pb-0.5 [scrollbar-width:none]">
            {sectorOptions.map(([label, n]) => (
              <Chip key={label} active={sector === label} onClick={() => setSector(sector === label ? null : label)}>
                {label} <span className="opacity-60">{n}</span>
              </Chip>
            ))}
          </div>
        )}

        {/* City chips */}
        {cityOptions.length > 1 && (
          <div className="mt-2 flex items-center gap-2 overflow-x-auto px-5 pb-0.5 [scrollbar-width:none]">
            {cityOptions.map(([label, n]) => (
              <Chip key={label} active={city === label} onClick={() => setCity(city === label ? null : label)}>
                <MapPin className="h-3 w-3" /> {label} <span className="opacity-60">{n}</span>
              </Chip>
            ))}
          </div>
        )}
      </header>

      <div className="flex-1 space-y-3 px-4 py-4">
        {/* New since last visit */}
        {newSince > 0 && !hasFilters && !isLoading && (
          <div className="flex items-center justify-between rounded-xl bg-primary/10 px-4 py-2.5 text-sm text-foreground">
            <span>
              <strong>{newSince}</strong> new job{newSince === 1 ? "" : "s"} since your last visit
            </span>
            <button type="button" onClick={() => setNewSince(0)} aria-label="Dismiss" className="text-muted-foreground">
              <X className="h-4 w-4" />
            </button>
          </div>
        )}

        {jobsError ? (
          <ErrorState onRetry={retryLoadJobs} />
        ) : isLoading ? (
          <SkeletonList />
        ) : feedJobs.length === 0 ? (
          <EmptyState isFiltering={hasFilters} savedOnly={savedOnly} onClear={clearAll} />
        ) : (
          <>
            {visibleJobs.map((job: Job, i: number) => (
              <div
                key={job.id}
                className={i >= visibleCount - PAGE_SIZE ? "animate-in fade-in duration-300" : ""}
              >
                <JobCard
                  job={job}
                  saved={isSaved(job.id)}
                  query={searchQuery}
                  onOpen={() => openJob(job.id)}
                  onToggleSave={() => toggleSaved(job.id, job)}
                  onSkill={(s) => setSearchQuery(s)}
                  onSector={(s) => setSector(s)}
                  onCity={(c) => setCity(c)}
                  onToast={showToast}
                />
              </div>
            ))}

            {hasMore ? (
              <div ref={sentinelRef} className="py-4 text-center">
                <span className="text-xs text-muted-foreground">Loading more…</span>
              </div>
            ) : (
              <div className="py-6 text-center">
                <span className="text-xs text-muted-foreground">You&apos;re all caught up 🎉</span>
              </div>
            )}
          </>
        )}
      </div>

      {/* Back to top */}
      {showTop && (
        <button
          type="button"
          onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
          aria-label="Back to top"
          className="fixed bottom-24 right-4 z-20 flex h-11 w-11 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-lg animate-in fade-in"
        >
          <ArrowUp className="h-5 w-5" />
        </button>
      )}

      {/* Toast */}
      {toast && (
        <div className="fixed bottom-24 left-1/2 z-30 -translate-x-1/2 animate-in fade-in slide-in-from-bottom-2">
          <div className="flex items-center gap-2 rounded-full bg-foreground px-4 py-2 text-sm text-background shadow-lg">
            <Check className="h-4 w-4" /> {toast}
          </div>
        </div>
      )}
    </div>
  )
}

// ─── Small pieces ─────────────────────────────────────────────────────────────

function countBy(jobs: Job[], key: string): [string, number][] {
  const map = new Map<string, number>()
  for (const j of jobs) {
    const v = j[key]
    if (v) map.set(v, (map.get(v) || 0) + 1)
  }
  return [...map.entries()].sort((a, b) => b[1] - a[1])
}

function Chip({
  active, onClick, children,
}: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={active}
      className={`inline-flex shrink-0 items-center gap-1.5 whitespace-nowrap rounded-full border px-3 py-1.5 text-xs font-medium transition ${
        active
          ? "border-primary bg-primary text-primary-foreground"
          : "border-border bg-card text-foreground hover:bg-secondary"
      }`}
    >
      {children}
    </button>
  )
}

function ErrorState({ onRetry }: { onRetry: () => void }) {
  return (
    <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
      <AlertCircle className="h-8 w-8 text-destructive" />
      <p className="font-semibold text-foreground">We couldn&apos;t load jobs</p>
      <p className="text-sm text-muted-foreground">Check your connection and try again.</p>
      <Button variant="outline" className="mt-2 rounded-xl" onClick={onRetry}>
        Try again
      </Button>
    </div>
  )
}

function EmptyState({
  isFiltering, savedOnly, onClear,
}: { isFiltering: boolean; savedOnly: boolean; onClear: () => void }) {
  if (savedOnly) {
    return (
      <div className="flex flex-col items-center gap-2 py-16 text-center">
        <p className="font-semibold text-foreground">No saved jobs yet</p>
        <p className="text-sm text-muted-foreground">Tap the bookmark on any job to keep it here.</p>
        <Button variant="outline" size="sm" className="mt-2 rounded-xl" onClick={onClear}>
          Browse all jobs
        </Button>
      </div>
    )
  }
  if (isFiltering) {
    return (
      <div className="flex flex-col items-center gap-2 py-16 text-center">
        <p className="font-semibold text-foreground">No matching jobs</p>
        <p className="text-sm text-muted-foreground">Try different keywords or remove a filter.</p>
        <Button variant="outline" size="sm" className="mt-2 rounded-xl" onClick={onClear}>
          Clear filters
        </Button>
      </div>
    )
  }
  return (
    <div className="flex flex-col items-center gap-2 py-20 text-center">
      <p className="font-semibold text-foreground">No jobs available right now</p>
      <p className="text-sm text-muted-foreground">Check back soon for new listings.</p>
    </div>
  )
}

function SkeletonList() {
  return (
    <>
      {Array.from({ length: 5 }).map((_, i) => (
        <div key={i} className="rounded-2xl border border-border bg-card p-4 shadow-sm">
          <div className="flex items-start gap-3">
            <div className="h-11 w-11 animate-pulse rounded-full bg-muted" />
            <div className="flex-1 space-y-2">
              <div className="h-3.5 w-3/4 animate-pulse rounded bg-muted" />
              <div className="h-3 w-1/2 animate-pulse rounded bg-muted" />
            </div>
          </div>
          <div className="mt-3 flex gap-2">
            <div className="h-5 w-16 animate-pulse rounded-full bg-muted" />
            <div className="h-5 w-20 animate-pulse rounded-full bg-muted" />
          </div>
        </div>
      ))}
    </>
  )
}