"use client"

/**
 * Job posters built only from your existing fields:
 * id, title, company, locationLabel, skills, fieldLabel, postedAt, closingDate
 * (salary / typeLabel are used automatically if the job has them)
 *
 * - 6 layouts x 8 palettes = 48 looks, picked per job from its id,
 *   so every job keeps the same poster each time you scroll past it.
 * - "Restyle" cycles to a different look for that job.
 * - Caption is generated from the same data, editable, copyable.
 * - Download PNG (1080x1350) or share the image through the phone share sheet.
 *
 * Needs one dependency:  npm i html-to-image
 * (Glass effects use gradients instead of backdrop-filter so the PNG
 *  looks exactly like the preview.)
 */

import { forwardRef, useEffect, useMemo, useRef, useState } from "react"
import { Bookmark, Check, Copy, Download, Pencil, Share2, Shuffle } from "lucide-react"

type Job = any // swap for your real Job type

const BRAND = "Jobs" // <- put your app name here (shown small on the poster)
const W = 360
const H = 450 // exported at pixelRatio 3 => 1080 x 1350

// ─── Data helpers ─────────────────────────────────────────────────────────────

function hash(s: string): number {
  let h = 0
  for (let i = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0
  return Math.abs(h)
}

function splitSkills(skills?: string): string[] {
  if (!skills) return []
  return skills.split(/[,;|\n]/).map((s) => s.trim()).filter(Boolean)
}

function shortDate(iso?: string): string {
  if (!iso) return ""
  const d = new Date(iso)
  return isNaN(d.getTime()) ? "" : d.toLocaleDateString("en-GB", { day: "numeric", month: "short" })
}

function initialsOf(name = "?"): string {
  return name.split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase() || "?"
}

interface PosterData {
  title: string
  company: string
  loc: string
  field: string
  extras: string[]
  skills: string[]
  closing: string
  posted: string
  initials: string
}

function posterData(job: Job): PosterData {
  const generic = !job.company || job.company === "N/A" || job.company === "Company not listed"
  return {
    title: job.title || "Open role",
    company: generic ? "" : job.company,
    loc: (job.locationLabel || "").split(",").slice(0, 2).join(",").trim(),
    field: job.fieldLabel || "",
    extras: [job.typeLabel && job.typeLabel !== "Unknown" ? job.typeLabel : "", job.salary || ""].filter(Boolean),
    skills: splitSkills(job.skills).slice(0, 3),
    closing: shortDate(job.closingDate),
    posted: shortDate(job.postedAt),
    initials: initialsOf(generic ? job.title : job.company),
  }
}

// ─── Caption ──────────────────────────────────────────────────────────────────

const tag = (s: string) => "#" + s.replace(/[^a-zA-Z0-9]/g, "")

export function buildCaption(job: Job): string {
  const d = posterData(job)
  const skills = splitSkills(job.skills).slice(0, 4)
  const head = d.company ? `${d.title} at ${d.company}` : d.title
  const where = [d.loc, d.field, ...d.extras].filter(Boolean).join(" | ")
  const tags = [d.field, d.loc.split(",")[0], ...skills.slice(0, 2), "Hiring", "Jobs"]
    .filter(Boolean)
    .map(tag)
    .filter((t) => t.length > 1)
  return [
    head,
    where,
    skills.length ? `Skills: ${skills.join(", ")}` : "",
    d.closing ? `Apply before ${d.closing}.` : "",
    "",
    [...new Set(tags)].join(" "),
  ]
    .filter((l, i, a) => l || (i > 0 && a[i - 1]))
    .join("\n")
}

// ─── Palettes ─────────────────────────────────────────────────────────────────

const PALETTES = [
  { from: "#042f2e", via: "#0f766e", to: "#1e3a8a", glow: "#5eead4", ink: "#f0fdfa" }, // lagoon
  { from: "#1c0a0a", via: "#9f1239", to: "#ea580c", glow: "#fdba74", ink: "#fff7ed" }, // ember
  { from: "#1e1b4b", via: "#5b21b6", to: "#be185d", glow: "#f0abfc", ink: "#faf5ff" }, // violet
  { from: "#0f172a", via: "#334155", to: "#a16207", glow: "#fcd34d", ink: "#fefce8" }, // slate gold
  { from: "#052e16", via: "#166534", to: "#0e7490", glow: "#86efac", ink: "#f0fdf4" }, // forest
  { from: "#0c1a3a", via: "#1d4ed8", to: "#0891b2", glow: "#7dd3fc", ink: "#eff6ff" }, // ocean
  { from: "#2a0a18", via: "#be123c", to: "#7c3aed", glow: "#fda4af", ink: "#fff1f2" }, // rose
  { from: "#0b2530", via: "#0e7490", to: "#f97316", glow: "#fdba74", ink: "#ecfeff" }, // teal coral
]
type Palette = (typeof PALETTES)[number]

const SANS = `"Inter","Helvetica Neue",Arial,sans-serif`
const SERIF = `"Iowan Old Style","Palatino Linotype",Georgia,serif`

function titleSize(t: string, base = 30) {
  return t.length > 56 ? base - 9 : t.length > 40 ? base - 6 : t.length > 26 ? base - 3 : base
}

// ─── Shared poster pieces ─────────────────────────────────────────────────────

function Avatar({ d, p, size = 40 }: { d: PosterData; p: Palette; size?: number }) {
  return (
    <div
      style={{
        width: size,
        height: size,
        fontSize: size * 0.36,
        color: p.ink,
        background: `linear-gradient(135deg,${p.glow}66,rgba(255,255,255,.12))`,
        border: "1px solid rgba(255,255,255,.35)",
        boxShadow: `0 8px 24px -6px ${p.glow}88`,
      }}
      className="flex shrink-0 items-center justify-center rounded-full font-bold"
    >
      {d.initials}
    </div>
  )
}

function Pills({ d, color, border }: { d: PosterData; color: string; border: string }) {
  const items = [d.loc, d.field, ...d.extras].filter(Boolean)
  return (
    <div className="mt-3 flex flex-wrap gap-1.5">
      {items.map((t) => (
        <span
          key={t}
          style={{ color, border: `1px solid ${border}`, fontSize: 11 }}
          className="rounded-full px-2.5 py-1 font-medium"
        >
          {t}
        </span>
      ))}
    </div>
  )
}

function Skills({ d, color }: { d: PosterData; color: string }) {
  if (!d.skills.length) return null
  return (
    <p style={{ color, fontSize: 11, opacity: 0.8 }} className="mt-3">
      {d.skills.join("  /  ")}
    </p>
  )
}

function Foot({ d, color }: { d: PosterData; color: string }) {
  return (
    <div style={{ color, fontSize: 10, opacity: 0.75 }} className="mt-4 flex items-center justify-between">
      <span>{d.closing ? `Apply before ${d.closing}` : d.posted ? `Posted ${d.posted}` : ""}</span>
      <span className="font-semibold tracking-wide">{BRAND}</span>
    </div>
  )
}

