const TEMPLATES = [Aurora, Editorial, Ribbon, Monolith, Orbit, Stack]

// ─── Poster (fixed 360x450, exported at 3x) ───────────────────────────────────

export const Poster = forwardRef<HTMLDivElement, { job: Job; seed?: number }>(function Poster(
  { job, seed = 0 },
  ref,
) {
  const d = useMemo(() => posterData(job), [job])
  const h = hash(String(job.id ?? job.title))
  const T = TEMPLATES[(h + seed) % TEMPLATES.length]
  const p = PALETTES[(Math.floor(h / 7) + seed * 3) % PALETTES.length]
  return (
    <div ref={ref} style={{ width: W, height: H, fontFamily: SANS }} className="relative overflow-hidden">
      <T d={d} p={p} />
    </div>
  )
})

// Scales the 360x450 poster to the card width and adds a small mouse tilt.
function ScaledPoster({
  job, seed, innerRef, onClick,
}: { job: Job; seed: number; innerRef: React.Ref<HTMLDivElement>; onClick: () => void }) {
  const wrap = useRef<HTMLDivElement | null>(null)
  const [scale, setScale] = useState(1)
  const [tilt, setTilt] = useState({ x: 0, y: 0 })

  useEffect(() => {
    const el = wrap.current
    if (!el) return
    const ro = new ResizeObserver(() => setScale(el.clientWidth / W))
    ro.observe(el)
    setScale(el.clientWidth / W)
    return () => ro.disconnect()
  }, [])

  const onMove = (e: React.PointerEvent) => {
    if (e.pointerType !== "mouse" || !wrap.current) return
    const r = wrap.current.getBoundingClientRect()
    setTilt({ x: ((e.clientY - r.top) / r.height - 0.5) * -5, y: ((e.clientX - r.left) / r.width - 0.5) * 5 })
  }

  return (
    <div style={{ perspective: 900 }}>
      <div
        ref={wrap}
        role="button"
        tabIndex={0}
        aria-label={`View details for ${job.title}`}
        onClick={onClick}
        onKeyDown={(e) => e.key === "Enter" && onClick()}
        onPointerMove={onMove}
        onPointerLeave={() => setTilt({ x: 0, y: 0 })}
        className="relative w-full cursor-pointer overflow-hidden rounded-3xl shadow-[0_24px_50px_-18px_rgba(0,0,0,.55)] transition-transform duration-200 ease-out active:scale-[0.99]"
        style={{ height: `${scale * H}px`, transform: `rotateX(${tilt.x}deg) rotateY(${tilt.y}deg)` }}
      >
        <div style={{ transform: `scale(${scale})`, transformOrigin: "top left", width: W, height: H }}>
          <Poster ref={innerRef} job={job} seed={seed} />
        </div>
      </div>
    </div>
  )
}

// ─── Export helpers ───────────────────────────────────────────────────────────

async function posterBlob(node: HTMLElement): Promise<Blob> {
  const { toBlob } = await import("html-to-image")
  const blob = await toBlob(node, {
    pixelRatio: 3,
    cacheBust: true,
    width: W,
    height: H,
    style: { transform: "none", transformOrigin: "top left" },
  })
  if (!blob) throw new Error("export failed")
  return blob
}

function saveBlob(blob: Blob, name: string) {
  const url = URL.createObjectURL(blob)
  const a = document.createElement("a")
  a.href = url
  a.download = name
  a.click()
  setTimeout(() => URL.revokeObjectURL(url), 2000)
}

// ─── Feed card: poster + actions + caption ────────────────────────────────────

export function PosterCard({
  job, saved, onOpen, onToggleSave, onToast,
}: {
  job: Job
  saved: boolean
  onOpen: () => void
  onToggleSave: () => void
  onToast: (msg: string) => void
}) {
  const node = useRef<HTMLDivElement | null>(null)
  const [seed, setSeed] = useState(0)
  const [caption, setCaption] = useState(() => buildCaption(job))
  const [editing, setEditing] = useState(false)
  const [copied, setCopied] = useState(false)
  const [busy, setBusy] = useState(false)

  const fileName = `${(job.title || "job").toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 40)}.png`

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(caption)
      setCopied(true)
      onToast("Caption copied")
      setTimeout(() => setCopied(false), 1500)
    } catch {
      onToast("Could not copy")
    }
  }

  const download = async () => {
    if (!node.current || busy) return
    setBusy(true)
    try {
      saveBlob(await posterBlob(node.current), fileName)
      onToast("Poster saved")
    } catch {
      onToast("Could not create image")
    } finally {
      setBusy(false)
    }
  }

  const share = async () => {
    if (!node.current || busy) return
    setBusy(true)
    try {
      const blob = await posterBlob(node.current)
      const file = new File([blob], fileName, { type: "image/png" })
      if (navigator.canShare?.({ files: [file] })) {
        await navigator.share({ files: [file], text: caption })
      } else {
        saveBlob(blob, fileName)
        await navigator.clipboard.writeText(caption).catch(() => {})
        onToast("Poster saved, caption copied")
      }
    } catch {
      /* cancelled */
    } finally {
      setBusy(false)
    }
  }

  const btn =
    "inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-medium text-muted-foreground hover:bg-secondary hover:text-foreground disabled:opacity-50"

  return (
    <article>
      <ScaledPoster
        job={job}
        seed={seed}
        innerRef={node}
        onClick={onOpen}
      />

      <div className="mt-2 flex items-center justify-between px-1">
        <div className="flex items-center">
          <button type="button" onClick={onToggleSave} aria-pressed={saved} className={btn}>
            <Bookmark className={`h-4 w-4 ${saved ? "fill-primary text-primary" : ""}`} />
            {saved ? "Saved" : "Save"}
          </button>
          <button type="button" onClick={() => setSeed((s) => s + 1)} className={btn}>
            <Shuffle className="h-4 w-4" /> Restyle
          </button>
        </div>
        <div className="flex items-center">
          <button type="button" onClick={download} disabled={busy} className={btn} aria-label="Download poster">
            <Download className="h-4 w-4" />
          </button>
          <button type="button" onClick={share} disabled={busy} className={btn} aria-label="Share poster">
            <Share2 className="h-4 w-4" />
          </button>
        </div>
      </div>

      <div className="mt-1 rounded-2xl border border-border bg-card p-3">
        {editing ? (
          <textarea
            value={caption}
            onChange={(e) => setCaption(e.target.value)}
            rows={7}
            className="w-full resize-none rounded-lg bg-secondary p-2 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-primary/25"
          />
        ) : (
          <p className="line-clamp-4 whitespace-pre-line text-xs leading-relaxed text-muted-foreground">{caption}</p>
        )}
        <div className="mt-2 flex items-center gap-1">
          <button type="button" onClick={copy} className={btn}>
            {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />} Copy caption
          </button>
          <button type="button" onClick={() => setEditing((v) => !v)} className={btn}>
            <Pencil className="h-4 w-4" /> {editing ? "Done" : "Edit"}
          </button>
        </div>
      </div>
    </article>
  )
}